using System;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Shell;
namespace ClearSpace {
public sealed class SoftwareUpdateView {
 public Window Window;public SoftwareRelease Release;public ProgressBar Progress;public TextBlock ProgressText,State;public Button Install,Cancel,Later;
}
public static class UpdateDialogs {
 static TextBlock Text(string value,int size=15){return new TextBlock{Text=value,FontSize=size,Foreground=App.Brush("#DFEAF2"),TextWrapping=TextWrapping.Wrap,LineHeight=size+9};}
 static void Name(Window window,FrameworkElement element,string name){element.Name=name;window.RegisterName(name,element);}
 static Window Create(Window owner,string title,out Grid body){
  var window=new Window{Owner=owner,Title=UiText.T(title),Icon=owner.Icon,Width=660,Height=470,MinWidth=520,MinHeight=360,WindowStyle=WindowStyle.None,AllowsTransparency=true,ResizeMode=ResizeMode.CanResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,ShowInTaskbar=false,Background=System.Windows.Media.Brushes.Transparent,Foreground=App.Brush("#DFEAF2"),FontFamily=owner.FontFamily,FontSize=14,Resources=owner.Resources,UseLayoutRounding=true};
  WindowChrome.SetWindowChrome(window,new WindowChrome{CaptionHeight=52,ResizeBorderThickness=new Thickness(6),GlassFrameThickness=new Thickness(0),CornerRadius=new CornerRadius(10),UseAeroCaptionButtons=false});
  window.Width=Math.Min(window.Width,Math.Max(520,SystemParameters.WorkArea.Width-32));window.Height=Math.Min(window.Height,Math.Max(360,SystemParameters.WorkArea.Height-40));NameScope.SetNameScope(window,new NameScope());UiMotion.SetEnabled(window,UiMotion.GetEnabled(owner));
  var surface=new Grid();surface.RowDefinitions.Add(new RowDefinition{Height=new GridLength(52)});surface.RowDefinitions.Add(new RowDefinition());var frame=new Border{Background=App.Brush("#161D25"),BorderBrush=App.Brush("#405563"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Child=surface};Name(window,frame,"DialogSurface");window.Content=frame;UiMotion.Dialog(window,frame);
  var caption=new Grid{Background=App.Brush("#1D2A34")};Name(window,caption,"DialogCaption");caption.ColumnDefinitions.Add(new ColumnDefinition());caption.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var heading=Text(title,17);heading.Margin=new Thickness(20,0,0,0);heading.VerticalAlignment=VerticalAlignment.Center;caption.Children.Add(heading);var close=new Button{Content="×",FontSize=22,Width=50,Background=System.Windows.Media.Brushes.Transparent,BorderThickness=new Thickness(0),Padding=new Thickness(0)};WindowChrome.SetIsHitTestVisibleInChrome(close,true);Name(window,close,"DialogClose");close.Click+=(s,e)=>window.Close();Grid.SetColumn(close,1);caption.Children.Add(close);surface.Children.Add(caption);
  body=new Grid{Margin=new Thickness(24,20,24,22)};Grid.SetRow(body,1);surface.Children.Add(body);return window;
 }
 public static Window Highlights(Window owner){
  Grid body;var window=Create(owner,"本版更新内容",out body);window.Height=Math.Min(window.Height,370);body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition());body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var version=Text("Clarity "+ReleaseVersion.Display+" · "+UiText.T("内部构建 ")+ReleaseVersion.Build,17);version.FontWeight=FontWeights.SemiBold;version.Margin=new Thickness(0,0,0,16);body.Children.Add(version);var summary=Text(ReleaseHighlights.Current);Name(window,summary,"ReleaseSummary");var scroll=new ScrollViewer{Content=summary,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);body.Children.Add(scroll);var done=new Button{Content="关闭",MinWidth=100,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,18,0,0)};done.Click+=(s,e)=>window.Close();Grid.SetRow(done,2);body.Children.Add(done);UiText.Attach(window);return window;
 }
 public static SoftwareUpdateView Update(Window owner,SoftwareRelease release){
  Grid body;var window=Create(owner,"发现新版本",out body);body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition());body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
  var version=Text("Clarity "+release.Label,22);version.FontWeight=FontWeights.SemiBold;version.Foreground=App.Brush("#39C5BB");version.Margin=new Thickness(0,0,0,16);Name(window,version,"UpdateVersion");body.Children.Add(version);var notes=Text(String.IsNullOrWhiteSpace(release.Notes)?UiText.T("发现可用更新"):release.Notes);Name(window,notes,"SoftwareNotes");var scroll=new ScrollViewer{Content=notes,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,0,0,14)};Grid.SetRow(scroll,1);body.Children.Add(scroll);
  var progressPanel=new StackPanel();var state=Text("");state.Visibility=Visibility.Collapsed;Name(window,state,"UpdateState");progressPanel.Children.Add(state);var bar=new ProgressBar{Height=10,Minimum=0,Maximum=100,Foreground=App.Brush("#39C5BB"),Background=App.Brush("#344651"),Margin=new Thickness(0,8,0,8),Visibility=Visibility.Collapsed};Name(window,bar,"UpdateProgress");progressPanel.Children.Add(bar);var progressText=Text("",13);progressText.Visibility=Visibility.Collapsed;Name(window,progressText,"UpdateProgressText");progressPanel.Children.Add(progressText);Grid.SetRow(progressPanel,2);body.Children.Add(progressPanel);
  var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,20,0,0)};var later=new Button{Content="稍后",MinWidth=88,Margin=new Thickness(0,0,10,0)};Name(window,later,"UpdateLater");actions.Children.Add(later);var cancel=new Button{Content="取消下载",Visibility=Visibility.Collapsed,Margin=new Thickness(0,0,10,0)};Name(window,cancel,"CancelSoftware");actions.Children.Add(cancel);var install=new Button{Content="下载并更新",MinWidth=145,Background=App.Brush("#39C5BB"),Foreground=App.Brush("#083F3A")};Name(window,install,"InstallSoftware");actions.Children.Add(install);Grid.SetRow(actions,3);body.Children.Add(actions);UiText.Attach(window);return new SoftwareUpdateView{Window=window,Release=release,Progress=bar,ProgressText=progressText,State=state,Install=install,Cancel=cancel,Later=later};
 }
}
}
